/* ASE-COM01: fictional commercial presentation only. No financial calculation or authority. */
(() => {
  'use strict';
  const $=id=>document.getElementById(id);
  const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const activities=['Consultar y compartir mi código autorizado','Consultar mis clientes atribuidos','Consultar mis ventas y renovaciones elegibles','Consultar mi estado de comisiones'];
  // Symbolic references are not redeemable codes, real account identifiers or executable grants.
  const examples={aurora:['A','Dra. Irene del Bosque','Dr. Samuel del Río'],bruno:['B','Dra. Alba del Prado','Dr. Elías del Mar'],cora:['C','Dra. Nerea del Valle','Dr. Iván de la Sierra'],diego:['D','Dra. Inés del Campo','Dr. Leo de la Fuente'],elisa:['E','Dra. Vera del Cielo','Dr. Simón del Puerto'],mar:['F','Dra. Eva del Pinar','Dr. Teo del Lago']};
  const notice='<p class="commercial-note"><strong>PROPUESTO · SIN CONECTAR.</strong> Personas y movimientos ficticios. No representa permisos, pagos ni comisiones reales.</p>';
  const dialog=document.createElement('dialog');dialog.id='commercial-activity';dialog.setAttribute('aria-labelledby','commercial-activity-title');dialog.setAttribute('aria-describedby','commercial-activity-description');document.body.append(dialog);
  const showActivity=window.ASE_VIS01_UI.setupDialog(dialog);
  let current=null,replays=0;
  function code(example){return `Código de ejemplo · ${example[0]} — NO VÁLIDO`;}
  function conditions(example,stage){return `<dl class="commercial-terms"><div><dt>Código del asesor</dt><dd>${example?esc(code(example)):'Sin código comercial propuesto para este integrante.'}</dd></div><div><dt>Oferta al cliente</dt><dd>Referencia histórica: 15% de descuento al cliente. Aplicabilidad, vigencia y renovaciones pendientes; no aplicado.</dd></div><div><dt>Porcentaje de comisión</dt><dd>PENDIENTE DE DEFINICIÓN</dd></div><div><dt>Base de cálculo</dt><dd>PENDIENTE DE DEFINICIÓN</dd></div><div><dt>Recurrencia</dt><dd>Incluye renovaciones pagadas elegibles, mensuales y anuales, mientras continúen la relación de pago del médico y el perfil elegible activo. No requiere reingresar el código.</dd></div><div><dt>Estado y alcance comercial</dt><dd>Propuesta sin habilitar · sólo actividad propia. ${stage==='SUSPENDED'?'Suspensión de acceso: conserva la historia; los derechos económicos requieren política independiente.':'La categoría interna no concede funciones comerciales automáticamente.'}</dd></div></dl>`;}
  function mount(){
    const detail=$('advisor-detail'),matrix=$('operational-matrix');
    if(!matrix || $('commercial-proposal'))return;
    const example=detail.dataset.category==='ADVISOR'?examples[detail.dataset.memberId]:null;
    const section=document.createElement('section');section.id='commercial-proposal';section.className='commercial-group';
    section.innerHTML=`<div class="family-heading"><div class="commercial-heading"><span class="family-title">CAPTACIÓN Y VENTAS</span><span class="family-count">4 actividades propuestas · sin permisos ejecutables</span></div><button class="family-toggle" type="button" id="commercial-expand" aria-expanded="false" aria-controls="commercial-proposals-body" aria-label="Expandir Captación y ventas">Expandir</button></div><div class="family-body" id="commercial-proposals-body" hidden>${notice}<p class="group-note">El Director podrá combinar estas actividades con las familias operativas. Un asesor de ventas sigue siendo Asesor, con permisos individuales.</p>${activities.map((a,i)=>`<label class="capability-row" for="commercial-proposed-${i}"><input id="commercial-proposed-${i}" type="checkbox" disabled aria-describedby="commercial-pending-${i}"><span class="capability-text"><span class="capability-label">${a}</span><span class="capability-description" id="commercial-pending-${i}">Propuesto: catálogo, consumidor y autorización pendientes.</span></span></label>`).join('')}<p class="group-note">No concede fijar descuentos o tasas, cambiar atribución, aprobar ajustes ni liquidar. Un Master necesitará delegación comercial expresa; su delegación operativa actual no basta.</p></div>`;
    matrix.append(section);
    $('commercial-expand').onclick=()=>{const body=$('commercial-proposals-body'),button=$('commercial-expand');body.hidden=!body.hidden;button.setAttribute('aria-expanded',String(!body.hidden));button.textContent=body.hidden?'Expandir':'Contraer';button.setAttribute('aria-label',`${body.hidden?'Expandir':'Contraer'} Captación y ventas`);};
    const terms=document.createElement('details');terms.className='commercial-conditions';terms.id='commercial-conditions';terms.innerHTML=`<summary>CONDICIONES COMERCIALES</summary>${notice}${conditions(example,detail.dataset.stage)}<p class="commercial-note">El asesor no puede cambiar sus condiciones. Tasas, ofertas, ajustes, transferencias de atribución y liquidación requieren funciones de gestión autorizadas por separado.</p>${example?'<button type="button" id="preview-own-activity">Previsualizar mi actividad comercial · ejemplo</button><p class="commercial-note">Revisión de diseño: abre la vista propia de este asesor ficticio; no acredita acceso del Director o Master a información financiera real.</p>':'<p class="commercial-note">La designación Master o una propuesta de incorporación no asigna código, clientes ni beneficios económicos.</p>'}`;
    $('capabilities-form').after(terms);
    if(example)$('preview-own-activity').onclick=()=>{current={id:detail.dataset.memberId,name:detail.dataset.memberName,stage:detail.dataset.stage,example};replays=0;renderActivity();$('preview-own-activity').focus();showActivity();$('commercial-activity-title').focus();};
  }
  function renderActivity(){
    const {id,name,stage,example}=current;
    // Fixed synthetic examples, not an eligibility evaluator, ledger or settlement writer.
    const periods=[['m1','Mensual · contratación inicial'],['m2','Mensual · renovación 2'],['m3','Mensual · renovación 3'],['a1','Anual · contratación inicial'],['a2','Anual · renovación del segundo año']];
    const fixtures=periods.map(([period,label],i)=>({notification:`aviso-ficticio-${i}`,payment:`pago-ficticio-${example[0]}-${period}`,period,label,customer:`cliente-${example[0]}-${i<3?'1':'2'}`,profile:`perfil-${example[0]}-${i<3?'1':'2'}`,advisor:id,rule:'regla-ficticia-pendiente',doctor:example[i<3?1:2]}));
    const messages=[...fixtures];
    if(replays){messages.push(fixtures[0],{...fixtures[0],notification:'otro-aviso-del-mismo-pago-ficticio'});}
    const projection=[...new Map(messages.map(f=>[JSON.stringify([f.payment,f.customer,f.profile,f.advisor,f.period,f.rule]),f])).values()];
    dialog.innerHTML=`<h2 id="commercial-activity-title" tabindex="-1">MI ACTIVIDAD COMERCIAL</h2><p id="commercial-activity-description">Vista propia de ${esc(name)} · asesor ficticio. Sin selector de otros asesores.</p>${notice}<section aria-labelledby="my-code-heading"><h3 id="my-code-heading">Mi código</h3><p class="symbolic-code">${esc(code(example))}</p><p class="commercial-note">Un asesor originador por cliente. La atribución validada deberá conservarse durante registro, verificación, contratación y renovaciones. Los ejemplos no redimen códigos.</p></section><section aria-labelledby="my-customers-heading"><h3 id="my-customers-heading">Mis clientes atribuidos · ejemplos</h3><ul class="commercial-customers">${example.slice(1).map((doctor,i)=>`<li data-own-customer="${esc(id)}"><strong>${esc(doctor)}</strong><span>Cuenta y perfil ficticios ${esc(example[0])}-${i+1} · origen comercial ${esc(name)} conservado.</span></li>`).join('')}</ul></section><section aria-labelledby="my-renewals-heading"><h3 id="my-renewals-heading">Suscripciones pagadas y renovaciones · ejemplos</h3><p class="commercial-note">Supuesto ilustrativo de perfil activo y periodo pagado elegible. Cada pago corresponde al médico cliente. La elegibilidad real está pendiente de contrato y evidencia de servidor.</p><ol class="commercial-periods">${projection.map(f=>`<li data-conceptual-result="${esc(f.payment)}" data-period="${f.period}" data-own-advisor="${esc(id)}"><strong>${esc(f.label)}</strong><span>${esc(f.doctor)} · ${esc(f.profile)} · ${esc(f.payment)}</span><span>Confirmación de pago y activación: supuestos ficticios separados. Un resultado conceptual por pago/periodo, no importe devengado.</span><span>Comisión: pendiente de regla · Liquidación: sin determinar.</span></li>`).join('')}</ol><p class="commercial-note">Ejemplo adicional: pago confirmado con activación pendiente → elegibilidad por resolver, sin resultado conceptual. Perfil público FREE activo sin pago → no genera un nuevo evento de comisión.</p></section><section aria-labelledby="my-statement-heading"><h3 id="my-statement-heading">Estado de comisiones y liquidación</h3><dl class="commercial-terms"><div><dt>Porcentaje y base</dt><dd>PENDIENTES DE DEFINICIÓN</dd></div><div><dt>Devengado por cliente y total</dt><dd>Sin calcular · no existe saldo financiero en esta vista.</dd></div><div><dt>Liquidado y pendiente de liquidación</dt><dd>Sin determinar · registro de liquidación separado.</dd></div></dl><p class="commercial-note">El descuento histórico al cliente del 15% no es la tasa de comisión. Su continuidad no está definida. ${stage==='SUSPENDED'?'La suspensión no borra historia ni decide por sí sola los derechos económicos.':''}</p></section><section class="commercial-replay" aria-labelledby="replay-heading"><h3 id="replay-heading">Ejemplo de notificación repetida</h3><p id="commercial-replay-status" role="status" aria-live="polite">${messages.length} avisos ficticios → ${projection.length} resultados conceptuales únicos.</p><p class="commercial-note">Deduplicación visual de fixtures, sin valor financiero. Repetir el mismo aviso o recibir otro aviso del mismo pago no añade otro resultado. No prueba idempotencia ni concurrencia financiera.</p><button id="commercial-replay" type="button">Repetir notificación de ejemplo</button></section><div class="dialog-actions"><button id="close-commercial" type="button">Cerrar vista ficticia</button></div>`;
    $('close-commercial').onclick=()=>dialog.close();
    $('commercial-replay').onclick=()=>{replays++;renderActivity();$('commercial-replay').focus();};
  }
  document.addEventListener('ase-vis01-detail-rendered',mount);
  mount();
})();
